import React, { useEffect, useState } from 'react';
import { exchangeToken } from './services/api'; // Import the exchangeToken function
import './App.css'; // Add a CSS file for styling

const App = () => {
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [userInput, setUserInput] = useState(''); // State to manage input text

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');
    const error = urlParams.get('error');

    if (success) {
      getAccessToken(); // Fetch access token if authorization is successful
    } else if (error) {
      console.error('Authorization error:', error);
      alert('Authorization failed. Please try again.');
    }
  }, []);

  const getAccessToken = async () => {
    try {
      const response = await exchangeToken(); // Fetch the token
      setIsAuthorized(true);
    } catch (error) {
      console.error('Error fetching access token:', error);
      alert('Could not fetch access token. Please try again.');
    }
  };

  return (
    <div className="app-container">
      <div className="content">
        <h1 className="title">Track Similarity App</h1>
        <button className="login-button" onClick={() => window.location.href = 'http://localhost:3001/login'}>
          Login with Spotify
        </button>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="Track name, artist, or album"
          className="text-input wide-text-input"
        />
      </div>
    </div>
  );
};

export default App;
